# carried gems at which a champion avoids losing fights on the way to tribute
GEM_BAG = 10
# local fight ratio below which a gem carrier flees toward an altar
GEM_FLEE = 1.0
# altars within this distance of a monolith are avoided when another altar exists
MONO_AVOID = 5

# ---- macros ----
def fight(t):
    # self-shield / self-heal when hurt
    if health() < HURT_FRAC * max_health():
        if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)):
            cast_self(0)
        elif ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)):
            cast_self(1)
    # stun first so the target loses its turn, then damage abilities
    if ability_ready(0) and slot_is_stun(0):
        cast_at_unit(0, t)
    elif ability_ready(1) and slot_is_stun(1):
        cast_at_unit(1, t)
    if ability_ready(0) and not slot_is_shield(0) and not slot_is_dash(0) and not slot_is_heal(0):
        cast_at_unit(0, t)
    if ability_ready(1) and not slot_is_shield(1) and not slot_is_dash(1) and not slot_is_heal(1):
        cast_at_unit(1, t)
    # ranged champions step away from an adjacent enemy instead of trading in place
    if i_am_ranged() and distance( unit_position(t), position() ) <= 1 and can_move():
        move_away_from( unit_position(t) )
        end_turn()
    attack(t)
    end_turn()

def go(t):
    if ability_ready(0) and slot_is_dash(0):
        dash_towards(0, t)
    elif ability_ready(1) and slot_is_dash(1):
        dash_towards(1, t)
    move_towards(t)

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep home = spawn_region(ally())
# altars not within reach of a monolith (all altars when the map has no monolith)
keep safe_all = minus( altars(), ring( monolith_tiles(), MONO_AVOID ) )

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( home, position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    # early game: Treasure shards for more gold; later: Jungle shards for camp durability
    if round_number() < 400:
        buy( shard_of(family_treasure(), stat_health()), shards_bought - strength_shards )
    else:
        buy( shard_of(family_jungle(), stat_health()), shards_bought - strength_shards )
    buy( shard(stat_strength()), strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 20% health normally, but at 50% when carrying gems.
# While something can hit us, walk toward spawn (recall would be cancelled); recall once clear.
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    if in_danger():
        move_towards( closest(home) )
        let chaser = first( filter( enemies_visible(), in_attack_range() ) )
        if exists(chaser):
            attack(chaser)
        end_turn()
    recall()
    end_turn()

# fight: focus the team target if in reach, else the weakest enemy champion in attack range
let inrange = filter( enemies_visible(), in_attack_range() )
let enemy = weakest( inrange )
if exists(enemy):
    # outnumbered and hurt: disengage toward spawn rather than trade into a losing fight
    if health() < 0.5 * max_health() and enemies_within(4) > 1 and local_strength(4) < 0.6:
        move_towards( closest(home) )
        end_turn()
    # carrying a bag and outgunned: break off toward an altar to tribute, not trade the bag away
    if gems() >= GEM_BAG and local_strength(4) < GEM_FLEE:
        let flee_safe = closest( ring(safe_all, 1) )
        if exists(flee_safe):
            move_towards( flee_safe )
            end_turn()
        let flee_dest = closest( ring(altars(), 1) )
        if exists(flee_dest):
            move_towards( flee_dest )
            end_turn()
    let tt = team_target()
    if exists(tt) and unit_health_frac(tt) > 0 and (distance( unit_position(tt), position() ) <= 1 or (i_am_ranged() and distance( unit_position(tt), position() ) <= 3)):
        fight(tt)
    else:
        set_team_target(enemy)
        fight(enemy)

if gems() > 0:
    let all_altars = altars()
    let locked = locked_altars()
    let open_altars = minus( all_altars, locked )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    # prefer open altars away from monoliths
    let safe_dest = closest( ring( minus(safe_all, locked), 1 ) )
    if exists(safe_dest):
        move_towards( safe_dest )
        end_turn()
    let dest = closest( ring(open_altars, 1) )
    if exists(dest):
        move_towards( dest )
        end_turn()
    # every known altar is locked: go to one anyway; tributing there attacks the lock
    let locked_altar = first( filter( all_altars, within(1, position()) ) )
    if exists(locked_altar):
        tribute(locked_altar)
        end_turn()
    move_towards( closest( ring(all_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0) and not slot_is_dash(0):
        cast_at_unit(0, camp)
    if ability_ready(1) and not slot_is_dash(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold so the capture timer keeps running,
# but only for up to 25 idle turns; after that, move on to the next goal
if contains(goals, position()) and turns_idle() < 25:
    end_turn()

# rich camp groups (static), and gem/elk groups as the fallback
keep rich_all = rich_spawns(10)
keep gem_goals_all = union( gem_cluster_tiles(), elk_tiles() )

let rich_pool = minus( rich_all, respawning_visible_spawns() )
# rich groups our allies already claim: join them first (commit together)
let rich_joined = minus( rich_pool, minus( rich_pool, claimed_by_allies() ) )
let rich_join = closest( rich_joined )
if exists(rich_join) and group_threat(rich_join) * group_hp(rich_join) <= health() * CLEAR_POWER * (1 + allies_within(4)):
    claim(rich_join)
    go( rich_join )
    end_turn()

# otherwise the closest rich group, if clearing it looks affordable
let rich_target = closest( rich_pool )
if exists(rich_target) and group_threat(rich_target) * group_hp(rich_target) <= health() * CLEAR_POWER * (1 + allies_within(4)):
    claim(rich_target)
    go( rich_target )
else:
    let gem_goals = minus( gem_goals_all, respawning_visible_spawns() )
    let gem_target = closest( gem_goals )
    if exists(gem_target):
        go( gem_target )
    else:
        move_towards( closest(goals) )

let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()

# v2: v1 plus team claims on rich camp groups.
# - Rich groups are split across allies: a rich group no ally has claimed is preferred,
#   and only if it is no more than RICH_BIAS times farther than the nearest gem/elk camp.
# - Otherwise the closest rich group (even if claimed) is taken, so allies commit together.
# - Gem/elk goals drop the claim. Feasibility gate and all other behaviour match v1.

# ---- tunable constants ----
# rough damage per turn one champion deals when clearing a camp group
CLEAR_POWER = 60
# health fraction below which shields / heals are used in a fight
HURT_FRAC = 0.5
# how many times farther a rich camp may be than a gem/elk camp and still be preferred
RICH_BIAS = 2

# ---- macros ----
def fight(t):
    # self-shield / self-heal when hurt
    if health() < HURT_FRAC * max_health():
        if ability_ready(0) and (slot_is_shield(0) or slot_is_heal(0)):
            cast_self(0)
        elif ability_ready(1) and (slot_is_shield(1) or slot_is_heal(1)):
            cast_self(1)
    # stun first so the target loses its turn, then damage abilities
    if ability_ready(0) and slot_is_stun(0):
        cast_at_unit(0, t)
    elif ability_ready(1) and slot_is_stun(1):
        cast_at_unit(1, t)
    if ability_ready(0) and not slot_is_shield(0) and not slot_is_dash(0) and not slot_is_heal(0):
        cast_at_unit(0, t)
    if ability_ready(1) and not slot_is_shield(1) and not slot_is_dash(1) and not slot_is_heal(1):
        cast_at_unit(1, t)
    # ranged champions step away from an adjacent enemy instead of trading in place
    if i_am_ranged() and distance( unit_position(t), position() ) <= 1 and can_move():
        move_away_from( unit_position(t) )
        end_turn()
    attack(t)
    end_turn()

def go(t):
    if ability_ready(0) and slot_is_dash(0):
        dash_towards(0, t)
    elif ability_ready(1) and slot_is_dash(1):
        dash_towards(1, t)
    move_towards(t)

# can our current group clear the camp group on spawn tile g in reasonable time?
def feasible(g):
    return group_threat(g) * group_hp(g) <= health() * CLEAR_POWER * (1 + allies_within(4))

# ---- draft ----
if is_draft():
    let pool = unpicked_champions()
    if available(pool, champ_vesper_vale()):
        pick(champ_vesper_vale())
    elif available(pool, champ_tavi()):
        pick(champ_tavi())
    elif available(pool, champ_marcella()):
        pick(champ_marcella())
    elif available(pool, champ_stellar()):
        pick(champ_stellar())
    elif available(pool, champ_ren()):
        pick(champ_ren())
    else:
        pick( random_champion(pool) )
    end_turn()

# ---- every turn ----
keep camp_spawns = camp_spawn_tiles()
keep home = spawn_region(ally())

if not alive() or channeling() or (not can_move() and not can_attack()):
    end_turn()

let at_spawn = contains( home, position() )
if at_spawn:
    let shards_bought = floor( gold() / 30 )
    let strength_shards = floor( shards_bought / 2 )
    # early game: Treasure shards for more gold; later: Jungle shards for camp durability
    if round_number() < 400:
        buy( shard_of(family_treasure(), stat_health()), shards_bought - strength_shards )
    else:
        buy( shard_of(family_jungle(), stat_health()), shards_bought - strength_shards )
    buy( shard(stat_strength()), strength_shards )
    # heal on spawn before heading back out, unless an enemy is already in reach
    if health() < max_health() and not exists(first(filter(enemies_visible(), in_attack_range()))):
        end_turn()

# retreat at 20% health normally, but at 50% when carrying gems.
# While something can hit us, walk toward spawn (recall would be cancelled); recall once clear.
if not at_spawn and (health() < 0.2 * max_health() or (gems() > 0 and health() < 0.5 * max_health())):
    if in_danger():
        move_towards( closest(home) )
        let chaser = first( filter( enemies_visible(), in_attack_range() ) )
        if exists(chaser):
            attack(chaser)
        end_turn()
    recall()
    end_turn()

# fight: focus the team target if in reach, else the weakest enemy champion in attack range
let inrange = filter( enemies_visible(), in_attack_range() )
let enemy = weakest( inrange )
if exists(enemy):
    # outnumbered and hurt: disengage toward spawn rather than trade into a losing fight
    if health() < 0.5 * max_health() and enemies_within(4) > 1 and local_strength(4) < 0.6:
        move_towards( closest(home) )
        end_turn()
    let tt = team_target()
    if exists(tt) and unit_health_frac(tt) > 0 and (distance( unit_position(tt), position() ) <= 1 or (i_am_ranged() and distance( unit_position(tt), position() ) <= 3)):
        fight(tt)
    else:
        set_team_target(enemy)
        fight(enemy)

if gems() > 0:
    let all_altars = altars()
    let open_altars = minus( all_altars, locked_altars() )
    let altar = first( filter( open_altars, within(1, position()) ) )
    if exists(altar):
        tribute(altar)
        end_turn()
    let dest = closest( ring(open_altars, 1) )
    if exists(dest):
        move_towards( dest )
        end_turn()
    # every known altar is locked: go to one anyway; tributing there attacks the lock
    let locked_altar = first( filter( all_altars, within(1, position()) ) )
    if exists(locked_altar):
        tribute(locked_altar)
        end_turn()
    move_towards( closest( ring(all_altars, 1) ) )
    end_turn()

# one camps_visible() query per turn, reused for both attack checks
let camps = camps_visible()

let camp = first( filter( camps, in_attack_range() ) )
if exists(camp):
    if ability_ready(0) and not slot_is_dash(0):
        cast_at_unit(0, camp)
    if ability_ready(1) and not slot_is_dash(1):
        cast_at_unit(1, camp)
    attack(camp)
    end_turn()

let goals = minus( camp_spawns, respawning_visible_spawns() )

# already standing on a cleared camp spawn: hold so the capture timer keeps running,
# but only for up to 25 idle turns; after that, move on to the next goal
if contains(goals, position()) and turns_idle() < 25:
    end_turn()

# rich camp groups (static), then gem/elk groups; each must pass the clearing test
keep rich_all = rich_spawns(10)
keep gem_goals_all = union( gem_cluster_tiles(), elk_tiles() )

let rich_target = closest( minus( rich_all, respawning_visible_spawns() ) )
let rich_free_target = closest( minus( rich_all, union( respawning_visible_spawns(), claimed_by_allies() ) ) )
let gem_target = closest( minus( gem_goals_all, respawning_visible_spawns() ) )

# prefer an unclaimed rich camp, unless it is much farther than the nearest gem/elk camp
if exists(rich_free_target) and feasible(rich_free_target) and (not exists(gem_target) or distance(rich_free_target, position()) <= RICH_BIAS * distance(gem_target, position())):
    claim(rich_free_target)
    go( rich_free_target )
elif exists(rich_target) and feasible(rich_target) and (not exists(gem_target) or distance(rich_target, position()) <= RICH_BIAS * distance(gem_target, position())):
    claim(rich_target)
    go( rich_target )
elif exists(gem_target) and feasible(gem_target):
    unclaim()
    go( gem_target )
elif exists(rich_target) and feasible(rich_target):
    claim(rich_target)
    go( rich_target )
else:
    unclaim()
    move_towards( closest(goals) )

let camp2 = first( filter( camps, in_attack_range() ) )
if exists(camp2):
    attack(camp2)
set_priority( 1 + random_int(100) )
end_turn()
